package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.security;import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.security.oauth2.jwt.Jwt;
class SecurityConfigTests{@Test void mapsModeratorRole(){Jwt jwt=new Jwt("t",Instant.now(),Instant.now().plusSeconds(60),Map.of("alg","HS256"),Map.of("sub","m1","roles",List.of("MODERATOR")));var a=new SecurityConfig.JwtRolesConverter().convert(jwt);assertTrue(a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_MODERATOR")));}}
